components.css:
.ds-tabs { background: var(--paper, #efe4cb); border-bottom: 3px double var(--ink, #17140e); font-family: var(--font-type, 'Courier Prime', monospace); }
.ds-tabs ol { display: flex; justify-content: center; gap: 2rem; height: 2.35rem; margin: 0; padding: 0; list-style: none; }
.ds-tabs a { position: relative; display: inline-flex; align-items: center; gap: 0.4rem; height: 100%; color: var(--ink-faint, #6b5f4b); font-size: 0.57rem; letter-spacing: 0.11em; text-transform: uppercase; text-decoration: none; transition: color 0.2s ease; }
.ds-tabs a span { color: var(--red, #9d2c1f); font-family: var(--font-display, 'Besley', serif); font-size: 0.63rem; }
.ds-tabs a::after { content: ''; position: absolute; right: 0; bottom: -1px; left: 0; height: 2px; background: transparent; }
.ds-tabs a:hover { color: var(--ink, #17140e); }
.ds-tabs a[aria-current="location"] { color: var(--ink, #17140e); }
.ds-tabs a[aria-current="location"]::after { background: var(--red, #9d2c1f); }
.ds-tabs a:focus-visible { outline: 2px solid var(--red, #9d2c1f); outline-offset: 2px; }

.ds-front-action { display: inline-flex; align-items: center; justify-content: space-between; gap: 1.5rem; min-width: 15rem; padding: 0.78rem 0.95rem; background: var(--red, #9d2c1f); color: var(--paper, #efe4cb); border-radius: 0; font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.6rem; letter-spacing: 0.13em; text-transform: uppercase; text-decoration: none; transition: background 0.2s ease; }
.ds-front-action:hover { background: var(--ink, #17140e); }
.ds-front-action:focus-visible { outline: 2px solid var(--red, #9d2c1f); outline-offset: 3px; }

.ds-press { display: inline-flex; align-items: center; gap: 0.55rem; min-height: 1.85rem; padding: 0.28rem 0.55rem; border: 1px solid rgb(23 20 14 / 0.34); border-radius: 0; background: transparent; color: var(--ink-soft, #3d3629); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.57rem; letter-spacing: 0.1em; text-transform: uppercase; cursor: pointer; transition: color 0.2s ease, border-color 0.2s ease, background 0.2s ease; }
.ds-press:hover { color: var(--ink, #17140e); border-color: var(--ink, #17140e); }
.ds-press[aria-pressed="true"] { color: var(--ink, #17140e); border-color: var(--red, #9d2c1f); background: rgb(157 44 31 / 0.08); }
.ds-press:focus-visible { outline: 2px solid var(--red, #9d2c1f); outline-offset: 3px; }
.ds-press__label span { color: var(--red, #9d2c1f); }
.ds-press__bars { display: inline-flex; align-items: flex-end; gap: 2px; height: 11px; }
.ds-press__bars i { display: block; width: 2px; height: 4px; background: currentColor; opacity: 0.6; transform-origin: bottom; }
.ds-press__bars i:nth-child(2) { height: 8px; }
.ds-press__bars i:nth-child(3) { height: 6px; }

.ds-photo { margin: 0; }
.ds-photo__frame { --photo-x: 0; --photo-y: 0; position: relative; aspect-ratio: 16 / 10; overflow: hidden; padding: 0.32rem; border: 1px solid var(--ink, #17140e); border-radius: 0; background: var(--paper-deep, #e4d5b6); }
.ds-photo__living { position: absolute; inset: 0.32rem; overflow: hidden; }
.ds-photo__misprint, .ds-photo__plate { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.ds-photo__misprint { filter: sepia(1) saturate(2) hue-rotate(-18deg) contrast(1.06) blur(0.5px); mix-blend-mode: multiply; opacity: 0.2; transform: translate(calc(var(--photo-x) * 3px), calc(var(--photo-y) * 2px)) scale(1.04); transition: transform 0.45s ease, opacity 0.45s ease; }
.ds-photo__plate { filter: sepia(0.62) saturate(0.72) contrast(1.04); transform: translate(calc(var(--photo-x) * -2px), calc(var(--photo-y) * -1.5px)) scale(1.01); transition: filter 0.5s ease, transform 0.4s ease; }
.ds-photo__frame:hover .ds-photo__plate { filter: sepia(0.16) saturate(1.08); transform: translate(calc(var(--photo-x) * -7px), calc(var(--photo-y) * -5px)) scale(1.04); }
.ds-photo__frame:hover .ds-photo__misprint { opacity: 0.28; transform: translate(calc(var(--photo-x) * 4px), calc(var(--photo-y) * 3px)) scale(1.05); }
.ds-photo__grain { position: absolute; inset: 0; background-image: radial-gradient(rgb(23 20 14 / 0.15) 0.55px, transparent 0.65px); background-size: 3px 3px; mix-blend-mode: multiply; opacity: 0.55; pointer-events: none; }
.ds-photo figcaption { display: flex; flex-wrap: wrap; gap: 0.3rem 0.55rem; padding-top: 0.5rem; color: var(--ink-faint, #6b5f4b); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.57rem; line-height: 1.45; }
.ds-photo figcaption span { color: var(--red, #9d2c1f); font-weight: 700; text-transform: uppercase; }

.ds-story { border-top: 3px double var(--ink, #17140e); padding-top: 1.5rem; color: var(--ink-soft, #3d3629); }
.ds-story h3 { margin: 0; color: var(--ink, #17140e); font-family: var(--font-display, 'Besley', serif); font-size: clamp(2.5rem, 6vw, 5.8rem); font-weight: 900; letter-spacing: -0.03em; line-height: 0.9; }
.ds-story__deck { max-width: 52ch; margin: 0.2rem 0 0; color: var(--ink-soft, #3d3629); font-size: 1.1rem; font-style: italic; }
.ds-story__meta { max-width: 52ch; margin: 0.55rem 0 0; padding-top: 0.38rem; border-top: 1px solid rgb(23 20 14 / 0.16); color: var(--ink-faint, #6b5f4b); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.57rem; letter-spacing: 0.09em; text-transform: uppercase; }
.ds-story__body { margin-top: 1rem; padding-top: 1rem; border-top: 1px solid rgb(23 20 14 / 0.34); }
.ds-story__lede { max-width: 64ch; margin: 0 0 1rem; font-size: 0.98rem; line-height: 1.68; }
.ds-story__lede::first-letter { float: left; padding: 0.08em 0.1em 0 0; color: var(--red, #9d2c1f); font-family: var(--font-display, 'Besley', serif); font-size: 3.9em; font-weight: 700; line-height: 0.74; }
.ds-story h4 { margin: 1.4rem 0 0.65rem; padding-bottom: 0.28rem; border-bottom: 1px solid rgb(23 20 14 / 0.34); color: var(--ink, #17140e); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.57rem; letter-spacing: 0.13em; text-transform: uppercase; }
.ds-story__findings { display: grid; gap: 0.55rem; margin: 0 0 1.25rem; padding: 0 0 0 1.6rem; font-size: 0.9rem; line-height: 1.55; }
.ds-story__stack { margin: 0; padding-top: 0.65rem; border-top: 1px solid rgb(23 20 14 / 0.16); color: var(--ink-faint, #6b5f4b); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.6rem; letter-spacing: 0.05em; line-height: 1.7; text-transform: uppercase; }
.ds-story__stack span { display: block; margin-bottom: 0.15rem; color: var(--red, #9d2c1f); font-size: 0.56rem; letter-spacing: 0.12em; }

.ds-workshop { width: 100%; border-collapse: collapse; color: var(--ink-soft, #3d3629); font-family: var(--font-body, 'Newsreader', serif); font-size: 0.9rem; line-height: 1.5; }
.ds-workshop thead th { padding: 0.45rem 0.65rem 0.6rem; border-bottom: 1px solid var(--ink, #17140e); color: var(--ink-faint, #6b5f4b); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.56rem; font-weight: 400; letter-spacing: 0.14em; text-align: left; text-transform: uppercase; }
.ds-workshop tbody th { width: 17%; padding: 0.9rem 0.65rem; border-bottom: 1px solid rgb(23 20 14 / 0.16); color: var(--ink, #17140e); font-family: var(--font-display, 'Besley', serif); font-size: 1.05rem; font-weight: 700; text-align: left; vertical-align: top; }
.ds-workshop tbody td { padding: 0.9rem 0.65rem; border-bottom: 1px solid rgb(23 20 14 / 0.16); vertical-align: top; }
.ds-workshop tbody td:last-child { color: var(--ink-faint, #6b5f4b); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.58rem; letter-spacing: 0.05em; text-transform: uppercase; }

.ds-row { display: grid; grid-template-columns: 4.6rem minmax(0, 1fr) auto; gap: 0.7rem; align-items: baseline; padding: 0.9rem 0.15rem; border-bottom: 1px solid rgb(23 20 14 / 0.16); color: var(--ink-soft, #3d3629); text-decoration: none; transition: color 0.2s ease, padding-left 0.2s ease; }
.ds-row:hover { padding-left: 0.4rem; color: var(--ink, #17140e); }
.ds-row:focus-visible { outline: 2px solid var(--red, #9d2c1f); outline-offset: 2px; }
.ds-row__label { color: var(--ink-faint, #6b5f4b); font-family: var(--font-type, 'Courier Prime', monospace); font-size: 0.57rem; letter-spacing: 0.12em; text-transform: uppercase; }
.ds-row__value { font-family: var(--font-body, 'Newsreader', serif); font-size: 0.9rem; overflow-wrap: anywhere; }
.ds-row svg { color: var(--red, #9d2c1f); }
